def least_capacity(weights, days):
    def can_ship(cap):
        d, cur = 1, 0
        for w in weights:
            if w > cap:
                return False
            if cur + w > cap:
                d += 1; cur = 0
            cur += w
        return d <= days
    lo, hi = max(weights), sum(weights)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_ship(mid):
            hi = mid - 1
        else:
            lo = mid + 1
    return lo

